const state = $input.first()?.json ?? {};
const documents = (Array.isArray(state.project_context?.documents) ? state.project_context.documents : []).filter((item) => item && item.document_id && ['parsed', 'ready', 'uploaded'].includes(String(item.status ?? '')));
const query = [state.project_question, state.research_frame, state.research_brief, state.step_title].filter(Boolean).join(' ').toLowerCase();
const terms = query.split(/[^\p{L}\p{N}]+/u).filter((term) => term.length > 1);
const score = (item) => { const text = [item.title, item.file_name, item.document_role].filter(Boolean).join(' ').toLowerCase(); return terms.reduce((total, term) => total + (text.includes(term) ? 2 : 0), 0) + (String(item.status) === 'parsed' ? 1 : 0); };
const selected = documents.slice().sort((left, right) => score(right) - score(left))[0] ?? null;
return [{ json: { ...state, initial_document: selected ? { document_id: String(selected.document_id), title: String(selected.title ?? selected.file_name ?? ''), status: String(selected.status ?? '') } : null } }];

const response = $input.first()?.json ?? {};
const state = $('Select Initial Project Document').first()?.json ?? {};
const result = response.structured_content ?? response.content ?? response;
return [{ json: { ...state, project_document_prefetch: result && typeof result === 'object' ? result : { status: 'unavailable', error: 'document_prefetch_failed' } } }];

const state = $input.first().json;
const output = state.decision_state.steps[state.step_key];
return [{ json: {
  run_id: state.run_id,
  step_key: state.step_key,
  step_order: state.step_order,
  status: 'completed',
  output,
  decision_state: state.decision_state,
} }];

const input = $input.first()?.json ?? {};
for (const field of ['run_id', 'step_key', 'step_title']) {
  if (typeof input[field] !== 'string' || !input[field].trim()) throw new Error('missing required field: ' + field);
}
if (!/^[0-9a-f-]{36}$/i.test(input.run_id)) throw new Error('run_id must be a UUID');
const stepOrder = Number(input.step_order);
if (!Number.isInteger(stepOrder) || stepOrder < 1 || stepOrder > 12) throw new Error('step_order must be between 1 and 12');
const list = (value) => Array.isArray(value) ? value.map(String).filter(Boolean) : [];
const decisionState = input.decision_state && typeof input.decision_state === 'object'
  ? input.decision_state
  : { steps: {}, evidence_index: {} };
const projectQuestion = String(input.project_question ?? input.question ?? '').trim();
return [{ json: {
  ...input,
  step_order: stepOrder,
  tenant_id: String(input.tenant_id ?? 'default'),
  access_groups: list(input.access_groups),
  project_types: list(input.project_types),
  geography: list(input.geography),
  metadata_filter: input.metadata_filter && typeof input.metadata_filter === 'object' ? input.metadata_filter : {},
  decision_state: decisionState,
  project_question: projectQuestion,
  retrieval_query: [projectQuestion, input.step_title].filter(Boolean).join('\n'),
} }];

