const request = $('Build Structured Decision Request').first().json;
const response = $input.first()?.json ?? {};
const primaryOutput = String(response.output_text ?? '').trim();
let parsed;
try {
  parsed = JSON.parse(primaryOutput);
} catch {
  const upstreamMessage = String(response.error?.message ?? response.error ?? 'empty_or_invalid_model_output').slice(0, 240);
  throw new Error('reader_chapter_model_failed: ' + upstreamMessage);
}
const state = request.state;
const readerChapter = String(parsed.reader_chapter ?? '').trim();
const leakagePatterns = [
  /step[_-]?\d{1,2}/i, /decision_state/i, /quality_gate/i, /evidence_index/i, /\bn8n\b/i,
  /(?:node|节点)[ _-]?(?:id|编号)/i, /(?:run|workflow|response)[ _-]?id/i,
  /\b(?:queued|running|completed|failed|cancelled|revision_required)\b/i,
  /\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/i,
  /(?:project|result|document):[a-z0-9._:-]{6,}/i, /\bE\d{3,}\b/i,
  /(?:page|block|chunk)[ _:-]?\d+/i, /\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b/i,
  /\b(?:phase\s*\d+|[GDP]\d+)\b/i,
];
if (!readerChapter) throw new Error('reader_chapter_empty');
if (leakagePatterns.some((pattern) => pattern.test(readerChapter))) throw new Error('reader_chapter_contains_internal_terms');
const decisionBrief = String(parsed.decision_brief ?? '').trim();
if (!decisionBrief) throw new Error('decision_brief_empty');
const citationSources = Array.isArray(response.tool_evidence) ? response.tool_evidence : [];
const citations = citationSources.filter((item) => item && typeof item === 'object').map((item) => ({ ...item, citation_id: String(item.citation_id ?? item.chunk_key ?? item.document_id ?? '').trim(), document_id: String(item.document_id ?? '').trim(), chunk_id: String(item.chunk_id ?? '').trim(), title: String(item.title ?? '').trim(), source_type: String(item.source_type ?? '').trim(), source_url: String(item.source_url ?? '').trim(), page_start: item.page_start ?? null, page_end: item.page_end ?? null, section: String(item.section ?? '').trim() })).filter((item, index, items) => item.citation_id && items.findIndex((candidate) => candidate.citation_id === item.citation_id) === index);
const diagnostics = (Array.isArray(response.tool_diagnostics) ? response.tool_diagnostics : []).filter((item) => item && typeof item === 'object');
const toolEvidence = Array.isArray(response.tool_evidence) ? response.tool_evidence : [];
const literatureEvidenceCount = toolEvidence.filter((item) => String(item?.source_type ?? '') === 'public_knowledge_graphrag').length;
const liveWebFulltextCount = toolEvidence.filter((item) => String(item?.source_type ?? '') === 'public_web_fulltext').length;
const projectEvidenceCount = toolEvidence.filter((item) => String(item?.source_type ?? '').startsWith('project_')).length;
const qualityGate = { evidence_count: citations.length, literature_evidence_count: literatureEvidenceCount, live_web_fulltext_count: liveWebFulltextCount, project_evidence_count: projectEvidenceCount, evidence_status: citations.length > 0 ? 'grounded' : 'insufficient_evidence', generation_status: 'completed', deepening_status: 'completed' };
const output = { step_key: state.step_key, step_order: state.step_order, title: state.step_title, research_brief: String(state.research_brief ?? ''), decision_brief: decisionBrief, reader_chapter: readerChapter, citations, diagnostics, quality_gate: qualityGate };
const nextDecisionState = {
  ...state.decision_state,
  steps: { ...(state.decision_state.steps ?? {}), [state.step_key]: output },
  evidence_index: { ...(state.decision_state.evidence_index ?? {}), [state.step_key]: output.citations },
  research_frame: String(state.research_frame ?? state.decision_state.research_frame ?? ''),
  research_plan: Array.isArray(state.research_plan) ? state.research_plan : (Array.isArray(state.decision_state.research_plan) ? state.decision_state.research_plan : []),
  current_step: state.step_key,
};
return [{ json: { result: {
  run_id: state.run_id, step_key: state.step_key, step_order: state.step_order, status: 'completed',
  output, decision_state: nextDecisionState,
} } }];

