const response = $input.first()?.json ?? {};
const calls = Array.isArray(response.tool_calls) ? response.tool_calls.filter((call) => call?.name && call?.call_id) : [];
if (!calls.length) throw new Error('invalid_agent_tool_call');
const state = $('Build Structured Decision Request').first().json.state ?? {};
return calls.map((call) => {
  const mcpToolName = String(call.name);
  const mcpArguments = call.arguments && typeof call.arguments === 'object' ? call.arguments : {};
  const toolArguments = mcpToolName === 'read_previous_chapter'
    ? { ...mcpArguments, completed_chapters: Object.values(state.decision_state?.steps ?? {}).filter((chapter) => chapter && Number(chapter.step_order ?? 0) < Number(state.step_order ?? 0)), current_step_order: Number(state.step_order ?? 0) }
    : mcpArguments;
  return { json: {
    ...response,
    tool_calls: calls,
    mcp_tool_name: mcpToolName,
    mcp_arguments: toolArguments,
    mcp_request_body: JSON.stringify({ history_id: state.history_id, tool_name: mcpToolName, arguments: toolArguments }),
    mcp_call_id: String(call.call_id),
    agent_turn: Number(response.agent_turn ?? 0) + 1,
    tool_call_count: Number(response.tool_call_count ?? 0) + calls.length,
  } };
});

const items = $input.all();
const preparedItems = typeof $('Prepare MCP Agent Tool Call').all === 'function' ? $('Prepare MCP Agent Tool Call').all() : [{ json: $('Prepare MCP Agent Tool Call').first().json }];
const prior = preparedItems[0]?.json ?? {};
const conversationItems = Array.isArray(prior.conversation_items) ? prior.conversation_items : [];
const responseItems = Array.isArray(prior.output) ? prior.output : [];
const stable = (value) => {
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}';
  return JSON.stringify(value);
};
const normalizedResults = items.map((item, index) => {
  const itemPrior = preparedItems[index]?.json ?? prior;
  const toolResult = item.json ?? {};
  return {
    tool_name: String(toolResult.tool_name ?? itemPrior.mcp_tool_name ?? ''),
    call_id: String(toolResult.mcp_call_id ?? itemPrior.mcp_call_id ?? ''),
    arguments: itemPrior.mcp_arguments && typeof itemPrior.mcp_arguments === 'object' ? itemPrior.mcp_arguments : {},
    is_error: toolResult.is_error === true,
    result: toolResult.structured_content ?? toolResult.content ?? toolResult,
  };
});
const newEvidence = normalizedResults.flatMap((entry) => {
  const source = entry.result && typeof entry.result === 'object' ? entry.result : {};
  const requested = entry.arguments;
  if (entry.is_error) return [];
  if (entry.tool_name === 'analyze_spatial_evidence') {
    const snapshotId = String(source.provenance?.snapshot_id ?? requested.history_id ?? 'offline_snapshot');
    return (Array.isArray(source.evidence) ? source.evidence : []).flatMap((evidenceItem) => {
      if (!evidenceItem || typeof evidenceItem !== 'object') return [];
      const evidenceId = String(evidenceItem.evidence_id ?? '').trim();
      if (!evidenceId) return [];
      return [{ citation_id: evidenceId, document_id: '', title: String(evidenceItem.title ?? '项目空间证据'), source_type: String(evidenceItem.source_type ?? 'project_spatial_evidence'), source_url: '', source_locator: String(evidenceItem.source_locator ?? ('spatial_evidence:' + evidenceId)), page_start: null, page_end: null, section: String(source.analysis ?? requested.analysis ?? ''), dataset_id: '', snapshot_id: snapshotId, dataset_checksum: String(source.provenance?.result_checksum ?? ''), complete: source.coverage?.complete === true, content: JSON.stringify(evidenceItem.content ?? evidenceItem) }];
    });
  }
  if (entry.tool_name === 'search_literature_evidence') {
    return (Array.isArray(source.evidence) ? source.evidence : []).flatMap((evidenceItem) => {
      if (!evidenceItem || typeof evidenceItem !== 'object') return [];
      const evidenceId = String(evidenceItem.evidence_id ?? '').trim();
      if (!evidenceId) return [];
      return [{ citation_id: evidenceId, document_id: '', title: String(evidenceItem.title ?? '公共知识库文献'), source_type: String(evidenceItem.source_type ?? 'public_knowledge_graphrag'), source_url: '', source_locator: String(evidenceItem.source_locator ?? ('literature:' + evidenceId)), page_start: evidenceItem.page_start ?? null, page_end: evidenceItem.page_end ?? null, section: String(source.mode ?? requested.mode ?? 'focused'), content: String(evidenceItem.content ?? '') }];
    });
  }
  if (entry.tool_name === 'read_project_document') {
    return (Array.isArray(source.blocks) ? source.blocks : []).flatMap((block) => {
      if (!block || typeof block !== 'object') return [];
      const page = Number(block.page ?? 0) || null;
      const locator = String(block.source_locator ?? (page ? 'page:' + page : 'block:' + String(block.chunk_id ?? '')));
      return [{ citation_id: String(block.chunk_id ?? source.selection_checksum ?? source.document_checksum ?? locator), document_id: String(source.document_id ?? requested.document_id ?? ''), title: String(block.filename ?? requested.document_id ?? '项目文档'), source_type: 'project_document', source_url: String(source.original_resource_uri ?? ''), source_locator: locator, page_start: page, page_end: page, section: String(block.heading ?? ''), content: String(block.text ?? '') }];
    });
  }
  if (entry.tool_name === 'fetch_public_web_page') {
    const urls = Array.isArray(source.urls) ? source.urls.map(String) : (Array.isArray(requested.urls) ? requested.urls.map(String) : []);
    const pages = Array.isArray(source.content) ? source.content : [];
    return pages.flatMap((page, index) => {
      const content = String(page ?? '').trim();
      if (!content) return [];
      const url = String(urls[index] ?? urls[0] ?? '').trim();
      const titleLine = content.split('\n').find((line) => line.trim().startsWith('#')) ?? '';
      const title = titleLine.replace(/^#+\s*/, '').trim() || url || '互联网公开资料';
      const locator = url || 'public_web:' + String(source.fetched_at ?? index);
      return [{ citation_id: 'public_web:' + locator, document_id: '', title, source_type: 'public_web_fulltext', source_url: url, source_locator: locator, page_start: null, page_end: null, section: '', provider: String(source.provider ?? requested.provider ?? 'anysearch'), fetched_at: String(source.fetched_at ?? ''), complete: true, content }];
    });
  }
  return [];
});
const toolEvidence = [...(Array.isArray(prior.tool_evidence) ? prior.tool_evidence : []), ...newEvidence].filter((item, index, collection) => item.citation_id && collection.findIndex((candidate) => candidate.citation_id === item.citation_id) === index);
const providerDiagnostics = normalizedResults.filter((entry) => {
  if (!['search_public_web', 'fetch_public_web_page'].includes(entry.tool_name)) return false;
  const result = entry.result && typeof entry.result === 'object' ? entry.result : {};
  return entry.is_error || ['unavailable', 'invalid_request', 'not_found'].includes(String(result.status ?? ''));
}).map((entry) => ({ kind: 'public_web_unavailable', tool_name: entry.tool_name, message: String(entry.result?.error ?? entry.result?.message ?? 'public_web_unavailable') }));
const toolDiagnostics = [...(Array.isArray(prior.tool_diagnostics) ? prior.tool_diagnostics : []), ...normalizedResults.filter((entry) => entry.is_error).map((entry) => ({ kind: 'tool_error', tool_name: entry.tool_name, message: String(entry.result?.message ?? entry.result?.error ?? 'tool_call_failed') })), ...providerDiagnostics];
const fingerprints = Array.isArray(prior.tool_result_fingerprints) ? prior.tool_result_fingerprints : [];
const newFingerprints = normalizedResults.map((entry) => stable({ tool_name: entry.tool_name, is_error: entry.is_error, result: entry.result })).filter((fingerprint) => !fingerprints.includes(fingerprint));
const isNewEvidence = newFingerprints.length > 0;
const staleToolTurns = isNewEvidence ? 0 : Number(prior.stale_tool_turns ?? 0) + 1;
const toolErrorCount = normalizedResults.some((entry) => entry.is_error) ? Number(prior.tool_error_count ?? 0) + 1 : 0;
const usage = prior.usage && typeof prior.usage === 'object' ? prior.usage : {};
const budget = Number(prior.context_budget_tokens ?? 24000);
const reserve = Number(prior.context_reserve_tokens ?? 6000);
const nextItems = [
  ...conversationItems,
  ...responseItems,
  ...normalizedResults.map((entry) => ({ type: 'function_call_output', call_id: entry.call_id, output: JSON.stringify(entry) })),
];
const measuredTokens = Number(usage.total_tokens ?? 0);
const contextTokens = measuredTokens > 0
  ? measuredTokens + Math.ceil(normalizedResults.reduce((total, entry) => total + JSON.stringify(entry).length, 0) / 4)
  : Math.ceil(JSON.stringify({ input: nextItems, instructions: prior.instructions, tools: prior.tools, text: prior.text }).length / 4);
const resolvedStopReason = contextTokens >= Math.max(1, budget - reserve)
  ? 'context_budget'
  : toolErrorCount >= Number(prior.tool_error_limit ?? 2)
    ? 'tool_errors'
    : staleToolTurns >= Number(prior.no_new_evidence_limit ?? 2)
    ? 'no_new_evidence'
    : null;
return [{ json: {
  ...prior,
  input: nextItems,
  conversation_items: nextItems,
  output: [],
  output_text: '',
  tool_calls: [],
  response_id: '',
  error: null,
  usage: { ...usage, estimated_context_tokens: contextTokens },
  stale_tool_turns: staleToolTurns,
  tool_error_count: toolErrorCount,
  tool_result_fingerprints: [...fingerprints, ...newFingerprints].slice(-32),
  tool_evidence: toolEvidence,
  tool_diagnostics: toolDiagnostics,
  stop_reason: resolvedStopReason,
  tool_choice: resolvedStopReason ? 'none' : undefined,
  tools: resolvedStopReason ? [] : prior.tools,
  instructions: resolvedStopReason
    ? String(prior.instructions ?? '') + '\n停止条件已满足：' + resolvedStopReason + '。请立即基于已获得的项目证据输出完整 reader_chapter，不要再调用工具。'
    : prior.instructions,
} }];
